class Tooltip:
    def __init__(self, widget, text):
        self.widget, self.text = widget, text
        self.timer = self.popup = None
        widget.bind("<Enter>", self.schedule, add="+")
        widget.bind("<Leave>", self.hide, add="+")
        widget.bind("<FocusIn>", self.schedule, add="+")
        widget.bind("<FocusOut>", self.hide, add="+")
        widget.bind("<Button-1>", self.show, add="+")
        widget.bind("<Destroy>", self.hide, add="+")
        widget.bind("<Return>",self.show,add="+")
        widget.bind("<space>",self.show,add="+")
        widget.bind("<Escape>",self.hide,add="+")

    def schedule(self, event=None):
        self.hide()
        self.timer = self.widget.after(300, self.show)

    def show(self, event=None):
        self.hide()
        if not self.widget.winfo_exists():
            return
        self.popup = tk.Toplevel(self.widget)
        self.popup.wm_overrideredirect(True)
        self.popup.attributes("-topmost", True)
        colors = ui.palette()
        label = tk.Label(self.popup, text=self.text, wraplength=330, justify="left", padx=14, pady=12,
                         background=colors.raised, foreground=colors.ink, font=ui.BODY, relief="flat",
                         highlightthickness=1, highlightbackground=colors.border_strong)
        label.pack()
        self.popup.update_idletasks()
        x = min(self.widget.winfo_rootx() + 20, self.widget.winfo_screenwidth() - self.popup.winfo_reqwidth() - 10)
        y = min(self.widget.winfo_rooty() + self.widget.winfo_height() + 8,
                self.widget.winfo_screenheight() - self.popup.winfo_reqheight() - 10)
        self.popup.geometry(f"+{max(0,x)}+{max(0,y)}")

    def hide(self, event=None):
        if self.timer is not None:
            self.widget.after_cancel(self.timer)
            self.timer = None
        if self.popup is not None:
            self.popup.destroy()
            self.popup = None


def help_icon(parent, key):
    icon = ttk.Label(parent, text="?", style="Help.TLabel", cursor="hand2", takefocus=True, width=2, anchor="center")
    icon.tooltip = Tooltip(icon, HELP.get(key, key))
    return icon
